public interface CustomerRepository extends JpaRepository<Customer, Integer> {

    // One SQL statement: customers LEFT JOIN orders. DISTINCT removes the
    // duplicate Customer instances that the join produces in the result set.
    @Query("select distinct c from Customer c left join fetch c.orders")
    List<Customer> findAllWithOrders();

    // Anti-join in JPQL: customers without orders.
    @Query("select c from Customer c where not exists "
         + "(select 1 from Order o where o.customer.id = c.id)")
    List<Customer> findWithoutOrders();
}

