public void transfer(DataSource ds, int from, int to, BigDecimal amount) throws SQLException {
    try (Connection con = ds.getConnection()) {
        con.setAutoCommit(false);                       // BEGIN is implicit
        try (PreparedStatement debit = con.prepareStatement(
                 "UPDATE account SET balance = balance - ? WHERE id = ?");
             PreparedStatement credit = con.prepareStatement(
                 "UPDATE account SET balance = balance + ? WHERE id = ?")) {
            debit.setBigDecimal(1, amount);
            debit.setInt(2, from);
            debit.executeUpdate();
            credit.setBigDecimal(1, amount);
            credit.setInt(2, to);
            credit.executeUpdate();
            con.commit();                               // all or nothing
        } catch (SQLException e) {
            con.rollback();                             // discard both updates
            throw e;
        }
    }
}

